package com.bank.risk;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class MinStackDemo {

    private static final Logger log = Logger.getLogger(MinStackDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        MinBalanceStack stack = new MinBalanceStack();

        stack.push(new BigDecimal("1000000"));   // Rajesh savings
        stack.push(new BigDecimal("250000"));     // Priya current
        stack.push(new BigDecimal("500000"));     // a new position

        log.info(() -> "Top balance: " + stack.top());
        log.info(() -> "Min balance: " + stack.getMin());  // 250000

        stack.pop();                                // remove 500000
        log.info(() -> "After pop, min: " + stack.getMin()); // still 250000

        stack.pop();                                // remove 250000
        log.info(() -> "After pop, min: " + stack.getMin()); // now 1000000
    }
}

