class MinBalanceStack {

    private final java.util.Deque<BigDecimal> main = new java.util.ArrayDeque<>();
    private final java.util.Deque<BigDecimal> mins = new java.util.ArrayDeque<>();

    void push(BigDecimal x) {
        main.push(x);
        // Push the smaller of x and the current minimum (compareTo for money).
        BigDecimal newMin = mins.isEmpty() ? x : (mins.peek().compareTo(x) <= 0 ? mins.peek() : x);
        mins.push(newMin);
    }

    BigDecimal pop() {
        mins.pop();            // keep both stacks aligned
        return main.pop();
    }

    BigDecimal top() {
        return main.peek();
    }

    BigDecimal getMin() {      // constant time: just the min-stack top
        return mins.peek();
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
